import type { NinjaAuthConfig, NinjaUser } from "./types/types";

const VERSION = "0.1.0";

class NinjaAuthClient {
    private config: NinjaAuthConfig | null = null;

    public readonly version = VERSION;

    public init(config: NinjaAuthConfig): void {
        if (!config.clientID) {
            throw new Error("NinjaAuth: clientID is required.");
        }

        if (!config.returnURL) {
            throw new Error("NinjaAuth: returnURL is required.");
        }

        this.config = {
            clientID: config.clientID,
            returnURL: config.returnURL
        };
    }

    public async logIn(): Promise<NinjaUser> {
        if (!this.config) {
            throw new Error(
                "NinjaAuth: call init() before logIn()."
            );
        }

        // TODO:
        // 1. Generate state
        // 2. Generate PKCE code_verifier
        // 3. Generate code_challenge
        // 4. Store temporary authentication state
        // 5. Redirect to Ninja Connect /v1/authorize

        throw new Error("NinjaAuth.logIn() is not implemented yet.");
    }

    public async logOut(): Promise<void> {
        // TODO
    }

    public async getUser(): Promise<NinjaUser | null> {
        // TODO
        return null;
    }
}

export const NinjaAuth = new NinjaAuthClient();